def _calibrate_len(text: str, lo: int, hi: int, pad_suffix: str) -> str:
    s = " ".join(text.strip().split())
    if len(s) < lo:
        need = lo - len(s)
        ext = (" " + pad_suffix.strip())
        while len(s) + len(ext) < lo:
            ext += " " + pad_suffix.strip()
        s = (s + ext)[: hi - 1].rstrip(" ,;.") + "."
        if len(s) < lo:
            s = s.ljust(lo, ".")
    elif len(s) > hi:
        cut = s[: hi - 1].rsplit(" ", 1)[0].rstrip(" ,;.") + "."
        if len(cut) >= lo:
            s = cut
        else:
            s = s[: hi - 1].rstrip(" ,;.") + "."
    assert lo <= len(s) <= hi, f"Length {len(s)} out of [{lo}, {hi}]: {s!r}"
    return s


