def build_skill_cells_dataframes():
    """Returns (df_empirical_30, df_gen5_6, df_poster_36) with calibrated character lengths."""
    import pandas as pd

    emp_rows = []
    gen5_rows = []
    poster_rows = []

    for c in RAW_SKILL_CELLS:
        gid = c["gen_id"]
        lvl = int(c["level_id"])
        b_str = LEVEL_BRACKET_STRS[lvl]
        t_lbl = COMPACT_TICK_LABELS[lvl]

        plain_desc = _calibrate_len(c["plain_desc"], 80, 105, "across production workflows")
        sub_summary = _calibrate_len(c["sub_summary"], 170, 200, "across production workflows")
        sub_use_cases = _calibrate_len(c["sub_use_cases"], 170, 200, "in documented deployments")
        sub_actions = _calibrate_len(c["sub_actions"], 170, 200, "during daily execution")
        sub_models = _calibrate_len(c["sub_models"], 170, 200, "in production releases")
        sub_surface = _calibrate_len(c["sub_surface"], 170, 200, "under operational SLAs")
        sub_scope = _calibrate_len(c["sub_scope"], 170, 200, "across the skill ladder")

        mega_kw_str = ", ".join(c["mega_kw"])
        mini_kw_str = ", ".join(c["mini_kw"])
        micro_list = list(c["micro_kw"])
        if len(" · ".join(micro_list)) > 36:
            # Select 2 shortest items from mini_kw so it's a 2-item proper subset <= 36 chars
            sorted_mini = sorted(c["mini_kw"], key=len)
            micro_list = [x for x in c["mini_kw"] if x in sorted_mini[:2]]
        micro_kw_str = " · ".join(micro_list)

        assert len(c["mega_kw"]) == 8, f"{gid}-L{lvl} mega_kw len != 8"
        assert 4 <= len(c["mini_kw"]) <= 6, f"{gid}-L{lvl} mini_kw len out of 4..6"
        assert 2 <= len(micro_list) <= 3, f"{gid}-L{lvl} micro_kw len out of 2..3"
        assert set(micro_list).issubset(set(c["mini_kw"])), f"{gid}-L{lvl} micro not subset of mini"
        assert set(c["mini_kw"]).issubset(set(c["mega_kw"])), f"{gid}-L{lvl} mini not subset of mega"

        cid = f"{gid}-L{lvl}"
        cell_tuple = (
            cid, gid, lvl, c["status"], c["learning_hours"], c["hardware_cap_usd"],
            b_str, b_str, t_lbl,
            c["single_task_tokens"], c["single_task_flops"], c["single_task_usd"], c["single_task_wh"],
            c["human_minutes"], c["ai_minutes"],
            c["user_share_pct"], c["token_share_pct"], c["spend_share_pct"],
            c["cell_name"], sub_surface, mega_kw_str,
            sub_scope, sub_scope, sub_scope, sub_scope
        )
        if gid == "G5":
            gen5_rows.append(cell_tuple)
        else:
            emp_rows.append(cell_tuple)

        enc_body = "\n".join([
            f"• Extended Summary: {sub_summary}",
            f"• Use Cases & Landmarks: {sub_use_cases}",
            f"• User Actions: {sub_actions}",
            f"• Models & Products: {sub_models}",
            f"• Surface & Hardware: {sub_surface}",
            f"• Scope & Evolution: {sub_scope}",
        ])

        poster_rows.append((
            cid, gid, lvl, c["cell_name"], c["short_header"],
            c["sae_human_action"], c["sae_ai_executes"],
            plain_desc, mega_kw_str, mini_kw_str, micro_kw_str,
            sub_summary, sub_use_cases, sub_actions, sub_models, sub_surface, sub_scope,
            enc_body, c.get("l6_pillars", "")
        ))

    cell_cols = [
        "cell_id", "gen_id", "level_id", "status", "learning_hours", "hardware_cap_usd",
        "level_bracket_str", "beeline_hrs_bracket", "compact_tick_label",
        "single_task_tokens", "single_task_flops", "single_task_usd", "single_task_wh",
        "human_minutes", "ai_minutes", "user_share_pct", "token_share_pct", "spend_share_pct",
        "user_first_title", "primary_surface_hw", "anchored_keywords_tutorials",
        "why_not_lower_L_minus_1", "why_not_higher_L_plus_1", "from_gen_G_minus_1", "to_gen_G_plus_1"
    ]
    poster_cols = [
        "cell_id", "gen_id", "level_id", "cell_name", "short_header",
        "sae_human_action", "sae_ai_executes",
        "plain_desc", "keywords_1line", "mini_keywords_subset", "micro_keywords_subset",
        "sub_summary", "sub_use_cases", "sub_actions", "sub_models", "sub_surface", "sub_scope",
        "encyclopedic_body", "l6_pillars"
    ]
    return (
        pd.DataFrame(emp_rows, columns=cell_cols),
        pd.DataFrame(gen5_rows, columns=cell_cols),
        pd.DataFrame(poster_rows, columns=poster_cols),
    )
